describe('Last Updated Timestamp for Live Data', () => {
    beforeEach(() => {
        cy.intercept('GET', '/api/live-data', {
            statusCode: 200,
            body: {
                data: {
                    lastUpdated: '2023-10-01T12:00:00Z'
                }
            }
        }).as('getLiveData');
        cy.visit('/live-data-page');
    });

    it('should display the last updated timestamp correctly', () => {
        cy.wait('@getLiveData');
        cy.get('.last-updated-timestamp').should('contain', '2023-10-01T12:00:00Z');
    });

    it('should handle missing last updated timestamp gracefully', () => {
        cy.intercept('GET', '/api/live-data', {
            statusCode: 200,
            body: {
                data: {}
            }
        }).as('getLiveDataMissingTimestamp');
        cy.reload();
        cy.wait('@getLiveDataMissingTimestamp');
        cy.get('.last-updated-timestamp').should('not.exist');
    });
});
